INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39378, 0, 0, 'Defilers! Wretches! Fiends! Begone from here!', 14, 0, 100, 0, 0, 18911, 'Rajh'),
(39378, 1, 0, 'Can you feel it? The blessed warmth of the sun?', 14, 0, 100, 0, 0, 18912, 'Rajh'),
(39378, 2, 0, 'I send you to your deity.', 14, 0, 100, 0, 0, 18914, 'Rajh to Player'),
(39378, 2, 1, 'I will take this life as an offering!', 14, 0, 100, 0, 0, 18913, 'Rajh to Player'),
(39378, 3, 0, 'Blazing rays of light, take me!', 14, 0, 100, 0, 0, 18910, 'Rajh to Player'),
(39378, 3, 1, 'I take this life as an offering!', 14, 0, 0, 0, 0, 18914, 'VO_HO_Rajh_Slay02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39425, 0, 0, 'Turn back, intruders! These halls must not be disturbed!', 14, 0, 100, 0, 0, 18580, 'Temple Guardian Anhuur - SAY_AGGRO'),
(39425, 1, 0, 'Beacons of light, bestow upon me your aegis!', 14, 0, 100, 0, 0, 18581, 'Temple Guardian Anhuur - SAY_SHIELD'),
(39425, 2, 0, '%s becomes protected by his defense beacons! Disable them by pulling the levers below!', 41, 0, 100, 0, 0, 0, 'Temple Guardian Anhuur - EMOTE_SHIELD'),
(39425, 3, 0, '%s is no longer protected by the beacons!', 41, 0, 100, 0, 0, 0, 'Temple Guardian Anhuur'),
(39425, 3, 1, 'A product of your own insolence.', 14, 0, 0, 0, 0, 18583, 'VO_HO_Anhuur_Slay02'),
(39425, 4, 0, 'I regret nothing.', 14, 0, 100, 0, 0, 18582, 'Temple Guardian Anhuur'),
(39425, 5, 0, 'What... have you... done?', 14, 0, 100, 0, 0, 18579, 'Temple Guardian Anhuur - SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39428, 0, 0, 'Ptah... is... no more...', 14, 0, 100, 0, 0, 18905, 'Earthrager Ptah - SAY_DEATH'),
(39428, 1, 0, 'More carrion for the swarm...', 14, 0, 100, 0, 0, 18906, 'Earthrager Ptah - SAY_AGGRO'),
(39428, 2, 0, 'Dust to dust.', 14, 0, 100, 0, 0, 18907, 'Earthrager Ptah - SAY_PLAYER_KILL'),
(39428, 2, 1, 'The earth TREMBLES!', 14, 0, 0, 0, 0, 18908, 'VO_HO_Ptah_Slay02'),
(39428, 3, 0, 'The earth TREMBLES!', 14, 0, 100, 0, 0, 18908, 'Earthrager Ptah - SAY_SPECIAL');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39587, 0, 0, 'Eons of darkness... by your hand.', 14, 0, 0, 0, 0, 18842, 'VO_HO_Isiset_Death'),
(39587, 0, 1, 'My luster... wanes.', 14, 0, 0, 0, 0, 18844, 'VO_HO_Isiset_Event01'),
(39587, 1, 0, 'Gaze to the heavens! What do you see?', 14, 0, 0, 0, 0, 18843, 'VO_HO_Isiset_Engage'),
(39587, 2, 0, 'Bask in my radiance!', 14, 0, 0, 0, 0, 18845, 'VO_HO_Isiset_Event02'),
(39587, 3, 0, 'The glimmer of your life, extinguished.', 14, 0, 0, 0, 0, 18846, 'VO_HO_Isiset_Slay01'),
(39587, 3, 1, 'Insignificant!', 14, 0, 0, 0, 0, 18847, 'VO_HO_Isiset_Slay02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39731, 0, 0, 'This chamber will flourish with your life energy!', 14, 0, 100, 0, 0, 18571, 'Ammunae - Aggro'),
(39731, 1, 0, 'Your life, UNLEASHED!', 14, 0, 100, 0, 0, 18572, 'Ammunae - Rampant Growth'),
(39731, 2, 0, 'The cycle continues...', 14, 0, 100, 0, 0, 18569, 'Ammunae - Death'),
(39731, 3, 0, 'Wither away!', 14, 0, 100, 0, 0, 18573, 'Ammunae - Slay 1'),
(39731, 3, 1, 'Waste of energy.', 14, 0, 100, 0, 0, 18574, 'Ammunae - Slay 2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39732, 0, 0, 'Yes! Harness... your... hatred.', 14, 0, 0, 0, 0, 18552, 'VO_HO_Setesh_Death'),
(39732, 1, 0, 'You fear that which you cannot control. But can you control your fear?', 14, 0, 0, 0, 0, 18553, 'VO_HO_Setesh_Engage'),
(39732, 2, 0, 'Embrace the end!', 14, 0, 0, 0, 0, 18555, 'VO_HO_Setesh_Slay01'),
(39732, 2, 1, 'Do you understand now?', 14, 0, 0, 0, 0, 18556, 'VO_HO_Setesh_Slay02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39788, 0, 0, 'This unit has been activated outside normal operating protocols. Downloading new operational parameters. Download complete. Full unit self defense routines are now active. Destruction of foreign units in the system shall now commence.', 14, 0, 100, 0, 0, 20857, 'Anraphet - SAY_INTRO'),
(39788, 1, 0, 'Purge of unauthorized entities commencing.', 14, 0, 100, 0, 0, 20862, 'Anraphet - SAY_AGGRO'),
(39788, 2, 0, 'Omega Stance activated. Annihilation of foreign unit is now imminent.', 14, 0, 100, 0, 0, 20861, 'Anraphet - SAY_OMEGA_STANCE'),
(39788, 2, 1, 'Purge complete.', 14, 0, 0, 0, 0, 20859, 'VO_HO_Anraphet_Slay02'),
(39788, 3, 0, 'Purge Complete.', 14, 0, 100, 0, 0, 20859, 'Anraphet - SAY_PLAYER_KILL'),
(39788, 3, 1, 'Target Annihilated.', 14, 0, 100, 0, 0, 20858, 'Anraphet - SAY_PLAYER_KILL'),
(39788, 4, 0, 'Anraphet unit shutting down...', 14, 0, 100, 0, 0, 20856, 'Anraphet - SAY_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(39908, 0, 0, 'This symbol, I think I\'ve seen this before... ', 12, 0, 100, 5, 0, 0, 'Brann Bronzebeard'),
(39908, 1, 0, 'Right, let\'s go! Just need to input the final entry sequence into the door mechanism... and...', 12, 0, 100, 5, 0, 20897, 'Brann Bronzebeard'),
(39908, 2, 0, 'That did the trick! The control room should be right behind this... oh... wow...', 12, 0, 100, 5, 0, 20898, 'Brann Bronzebeard'),
(39908, 3, 0, 'What? This isn\'t the control room! There\'s another entire defense mechanism in place, and the blasted Rock Troggs broke into here somehow. Troggs. Why did it have to be Troggs!', 12, 0, 100, 5, 0, 20899, 'Brann Bronzebeard'),
(39908, 4, 0, 'Ok, let me think a moment.', 12, 0, 100, 1, 0, 20900, 'Brann Bronzebeard'),
(39908, 5, 0, 'Mirrors pointing all over the place.', 12, 0, 100, 25, 0, 20902, 'Brann Bronzebeard'),
(39908, 6, 0, 'Four platforms with huge elementals.', 12, 0, 100, 25, 0, 20901, 'Brann Bronzebeard'),
(39908, 7, 0, 'I got it! I saw a tablet that mentioned this chamber. This is the Vault of Lights! Ok, simple enough. I need you adventurers to take out each of the four elementals to trigger the opening sequence for the far door!', 12, 0, 100, 5, 0, 20903, 'Brann Bronzebeard'),
(39908, 8, 0, 'One down!', 14, 0, 100, 5, 0, 20904, 'Brann Bronzebeard'),
(39908, 9, 0, 'Another one down! Just look at those light beams! They seem to be connecting to the far door!', 14, 0, 100, 5, 0, 20905, 'Brann Bronzebeard'),
(39908, 10, 0, 'One more elemental to go! The door is almost open!', 14, 0, 100, 5, 0, 20906, 'Brann Bronzebeard'),
(39908, 11, 0, 'That\'s it, you\'ve done it! The vault door is opening! Now we can... oh, no!', 14, 0, 100, 5, 0, 20907, 'Brann Bronzebeard'),
(39908, 12, 0, 'We\'ve done it! The control room is breached!', 14, 0, 100, 5, 0, 23709, 'Brann Bronzebeard'),
(39908, 13, 0, 'Here we go! Now this should only take a moment...', 14, 0, 100, 5, 0, 23710, 'Brann Bronzebeard');
