INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52409, 0, 0, 'Mortal Insects! You dare trespass into MY domain?  Your arrogance will be purged in living flame.', 14, 0, 100, 0, 0, 24517, 'Ragnaros - Emerge'),
(52409, 0, 1, 'Minions of fire! Purge the outsiders!', 14, 0, 100, 0, 0, 24514, 'Ragnaros adds 2'),
(52409, 0, 2, 'Denizens of flame, come to me!', 14, 0, 100, 0, 0, 24515, 'Ragnaros adds 3'),
(52409, 0, 3, 'Arise, servants of fire, consume their flesh!', 14, 0, 100, 0, 0, 24516, 'Ragnaros adds 4'),
(52409, 1, 0, 'Be consumed by flame!', 14, 0, 100, 0, 0, 24535, 'Ragnaros - Aggro'),
(52409, 1, 1, 'Begone from my realm, insects.', 14, 0, 100, 0, 0, 24533, 'Ragnaros - Aggro'),
(52409, 1, 2, 'The realm of fire will consume you!', 14, 0, 100, 0, 0, 24536, 'Ragnaros - Aggro'),
(52409, 2, 0, 'By fire be purged!', 14, 0, 100, 0, 0, 24532, 'Ragnaros - Wrath of Ragnaros'),
(52409, 3, 0, '|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s casts |cFFFF6600|Hspell:98164|h[Magma Trap]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Magma Trap'),
(52409, 4, 0, '|TInterface\\Icons\\spell_shaman_lavasurge.blp:20|t%s begins to cast |cFFFF0000|Hspell:98710|h[Sulfuras Smash]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros to Sulfuras Smash'),
(52409, 4, 1, 'Die!', 14, 0, 100, 0, 0, 24521, 'Ragnaros hammer drop 2'),
(52409, 4, 2, 'Your judgement has come!', 14, 0, 100, 0, 0, 24522, 'Ragnaros hammer drop 3'),
(52409, 5, 0, '|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s begins to cast |cFFFF0000|Hspell:98951|h[Splitting Blow]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Splitting Blow'),
(52409, 5, 1, 'Fall to your knees, mortals!  This ends now.', 14, 0, 100, 0, 0, 24524, 'Ragnaros hummer pickup 2'),
(52409, 5, 2, 'Sulfuras will be your end.', 14, 0, 100, 0, 0, 24525, 'Ragnaros hummer pickup 3'),
(52409, 6, 0, 'You will be crushed!', 14, 0, 100, 0, 0, 24520, 'Ragnaros - Splitting Blow'),
(52409, 6, 1, 'Your judgement has come!', 14, 0, 100, 0, 0, 24522, 'Ragnaros  Splitting Blow'),
(52409, 7, 0, 'Denizens of flame, come to me!', 14, 0, 100, 0, 0, 24515, 'Ragnaros - Invoke Sons'),
(52409, 7, 1, 'Arise, servants of fire, consume their flesh!', 14, 0, 100, 0, 0, 24516, 'Ragnaros - Invoke Sons'),
(52409, 8, 0, 'Enough! I will finish this.', 14, 0, 100, 0, 0, 24523, 'Ragnaros - Pick up Sulfuras'),
(52409, 8, 1, 'Fall to your knees, mortals!  This ends now.', 14, 0, 100, 0, 0, 24524, 'Ragnaros - Pick up Sulfuras'),
(52409, 8, 2, 'Sulfuras will be your end.', 14, 0, 100, 0, 0, 24525, 'Ragnaros - Pick up Sulfuras'),
(52409, 9, 0, '|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s begins to cast |cFFFF6600|Hspell:100171|h[World In Flames]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce World in Flames'),
(52409, 9, 1, 'Pathetic.', 14, 0, 100, 0, 0, 24530, 'Ragnaros kill 02'),
(52409, 9, 2, 'Die, insect!', 14, 0, 100, 0, 0, 24531, 'Ragnaros kill 01'),
(52409, 10, 0, '|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s begins to cast |cFFFF6600|Hspell:99171|h[Engulfing Flames]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Engulfing Flames'),
(52409, 11, 0, '%s is about to |cFFFF0000Emerge|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Emerge'),
(52409, 12, 0, 'Too soon! ... You have come too soon...', 14, 0, 100, 0, 0, 24519, 'Ragnaros - Defeated Normal'),
(52409, 12, 1, 'I will see you all burn.', 14, 0, 100, 0, 0, 24534, 'Ragnaros aggro 2'),
(52409, 12, 2, 'Be consumed by flame!', 14, 0, 100, 0, 0, 24535, 'Ragnaros aggro 3'),
(52409, 12, 3, 'The realm of fire will consume you!', 14, 0, 100, 0, 0, 24536, 'Ragnaros aggro 4'),
(52409, 13, 0, 'Too soon...', 14, 0, 100, 0, 0, 24528, 'Ragnaros - Submerge Heroic'),
(52409, 14, 0, 'Arrggh, outsiders - this is not your realm!', 14, 0, 100, 0, 0, 24527, 'Ragnaros - Emerge Heroic'),
(52409, 15, 0, 'When I finish this, your pathetic mortal world will burn with my vengeance!', 14, 0, 100, 0, 0, 24526, 'Ragnaros - Break Free'),
(52409, 16, 0, '|TInterface\\Icons\\inv_mace_2h_sulfuras_d_01.blp:20|t%s begins to cast |cFFFF6600|Hspell:100604|h[Empower Sulfuras]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Empower Sulfuras'),
(52409, 17, 0, '|TInterface\\Icons\\ability_mage_firestarter.blp:20|t%s casts |cFFFF0000|Hspell:100675|h[Dreadflame]|h|r!', 41, 0, 100, 0, 0, 0, 'Ragnaros - Announce Dreadflame'),
(52409, 18, 0, 'Pathetic.', 14, 0, 100, 0, 0, 24530, 'Ragnaros - Slay'),
(52409, 18, 1, 'This is MY realm!', 14, 0, 100, 0, 0, 24529, 'Ragnaros - Slay'),
(52409, 18, 2, 'Begone from my realm, insects.', 14, 0, 100, 0, 0, 24533, 'Ragnaros - Slay'),
(52409, 18, 3, 'Die!', 14, 0, 100, 0, 0, 24521, 'Ragnaros - Slay'),
(52409, 19, 0, 'No, noooo- This was to be my hour of triumph...', 14, 0, 100, 0, 0, 24518, 'Ragnaros - Death');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52530, 0, 0, 'I serve a new master now, mortals!', 14, 0, 100, 0, 0, 24426, 'Alysrazor aggro'),
(52530, 1, 0, 'The light...mustn\'t burn out...', 14, 0, 100, 0, 0, 24429, 'Alysrazor death'),
(52530, 2, 0, 'BURN!', 14, 0, 100, 0, 0, 24430, 'Alysrazor kill 01'),
(52530, 2, 1, 'For his glory!', 14, 0, 100, 0, 0, 24431, 'Alysrazor kill 02'),
(52530, 3, 0, 'These skies are MINE!', 14, 0, 100, 0, 0, 24434, 'Alysrazor spiral 01'),
(52530, 3, 1, 'I will burn you from the sky!', 14, 0, 100, 0, 0, 24435, 'Alysrazor spiral 02'),
(52530, 4, 0, 'Fire...fire...', 14, 0, 100, 0, 0, 24436, 'Alysrazor transition 01'),
(52530, 5, 0, 'Reborn in flame!', 14, 0, 100, 0, 0, 24437, 'Alysrazor transition 02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52558, 0, 0, 'Hah? Hruumph? Soft little fleshy-things? Here? Nuisances, nuisances!', 14, 0, 100, 0, 0, 24537, 'Lord Rhyolith - Engage'),
(52558, 1, 0, 'I\'ll crush you underfoot!', 14, 0, 100, 0, 0, 24557, 'Lord Rhyolith - Concussive Stomp 1'),
(52558, 1, 1, 'Stomp now.', 14, 0, 100, 0, 0, 24556, 'Lord Rhyolith - Concussive Stomp 2'),
(52558, 1, 2, 'Augh - smooshy little pests, look what you\'ve done!', 14, 0, 100, 0, 0, 24542, 'Rhyolith chunk 03'),
(52558, 1, 3, 'Uurrghh now you... you infuriate me!', 14, 0, 100, 0, 0, 24543, 'Rhyolith chunk 04'),
(52558, 1, 4, 'Oh you little beasts...', 14, 0, 100, 0, 0, 24544, 'Rhyolith chunk 05'),
(52558, 2, 0, '%s begins to drink from the magma pools.', 41, 0, 100, 0, 0, 0, 'Lord Rhyolith - Announce Drink Magma'),
(52558, 3, 0, 'Buuurrrnn!', 14, 0, 100, 0, 0, 24550, 'Lord Rhyolith - Heated Volcano 1'),
(52558, 3, 1, 'Succumb to living flame.', 14, 0, 100, 0, 0, 24551, 'Lord Rhyolith - Heated Volcano 2'),
(52558, 3, 2, 'Squeak, little pest.', 14, 0, 100, 0, 0, 24548, 'Rhyolith kill 03'),
(52558, 4, 0, '%s\'s armor is weakened by the active volcano.', 41, 0, 100, 0, 0, 0, 'Lord Rhyolith - Announce Obsidian Armor Weakened'),
(52558, 4, 1, 'Succumb to living flame.', 14, 0, 100, 0, 0, 24551, 'Rhyolith lava 02'),
(52558, 4, 2, 'My inner fire can never die.', 14, 0, 100, 0, 0, 24552, 'Rhyolith lava 03'),
(52558, 4, 3, 'Consume...', 14, 0, 100, 0, 0, 24553, 'Rhyolith lava 04'),
(52558, 4, 4, 'Flesh... burns!', 14, 0, 100, 0, 0, 24554, 'Rhyolith lava 05'),
(52558, 5, 0, 'Uurrghh now you... you infuriate me!', 14, 0, 100, 0, 0, 24543, 'Lord Rhyolith - Obsidian Armor Weakened 1'),
(52558, 5, 1, 'Oww now hey.', 14, 0, 100, 0, 0, 24540, 'Lord Rhyolith - Obsidian Armor Weakened 2'),
(52558, 5, 2, 'Graaahh!', 14, 0, 100, 0, 0, 24541, 'Lord Rhyolith - Obsidian Armor Weakened 3'),
(52558, 5, 3, 'Augh - smooshy little pests, look what you\'ve done!', 14, 0, 100, 0, 0, 24542, 'Lord Rhyolith - Obsidian Armor Weakened 4'),
(52558, 6, 0, 'Eons I have slept undisturbed... Now this... Creatures of flesh, now you will BURN!', 14, 0, 100, 0, 0, 24558, 'Rhyolith transform'),
(52558, 9, 0, 'Finished.', 14, 0, 100, 0, 0, 24546, 'Lord Rhyolith - Slay 1'),
(52558, 9, 1, 'So soft!', 14, 0, 100, 0, 0, 24547, 'Lord Rhyolith - Slay 2'),
(52558, 9, 2, 'Squeak, little pest.', 14, 0, 100, 0, 0, 24548, 'Lord Rhyolith - Slay 3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(52571, 0, 0, 'Very well. Witness the raw power of my new Lord!', 14, 0, 100, 0, 0, 24464, 'Majordomo Staghelm - Intro'),
(52571, 1, 0, 'The master\'s power takes on many forms...', 14, 0, 100, 0, 0, 24483, 'Majordomo Staghelm - Scorpion Form'),
(52571, 2, 0, '|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s transforms into a |c0087CEFA|Hspell:98379|h[Scorpion]|h|r!', 41, 0, 100, 0, 0, 0, 'Majordomo Staghelm - Announce Scorpion Form'),
(52571, 3, 0, 'Behold the rage of the Firelands!', 14, 0, 100, 0, 0, 24485, 'Majordomo Staghelm - Cat Form'),
(52571, 4, 0, '|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t%s transforms into a |c0087CEFA|Hspell:98374|h[Cat]|h|r!', 41, 0, 100, 0, 0, 0, 'Majordomo Staghelm - Announce Cat Form'),
(52571, 5, 0, 'Blaze of Glory!', 14, 0, 100, 0, 0, 24472, 'Majordomo Staghelm - Searing Seeds'),
(52571, 6, 0, '|c00FF0000Searing Seeds begin to grow!|r', 41, 0, 100, 0, 0, 0, 'Majordomo Staghelm - Announce Searing Seeds'),
(52571, 6, 1, 'Soon ALL of Azeroth will burn!', 14, 0, 100, 0, 0, 24479, 'Majordomo Staghelm - SAY_KILL_2'),
(52571, 6, 2, 'You stood in the fire!', 14, 0, 100, 0, 0, 24481, 'Majordomo Staghelm - SAY_KILL_3'),
(52571, 7, 0, 'Nothing but ash!', 14, 0, 100, 0, 0, 24478, 'Majordomo Staghelm - Burning Orbs'),
(52571, 8, 0, '|c00FF0000%s summons Burning Orbs!|r', 41, 0, 100, 0, 0, 0, 'Majordomo Staghelm - Announce Burning Orbs'),
(52571, 9, 0, 'Burn.', 14, 0, 100, 0, 0, 24477, 'Majordomo Staghelm - Slay'),
(52571, 9, 1, 'Soon ALL of Azeroth will burn!', 14, 0, 100, 0, 0, 24479, 'Majordomo Staghelm - Slay'),
(52571, 9, 2, 'So much power!', 14, 0, 100, 0, 0, 24480, 'Majordomo Staghelm - Slay'),
(52571, 9, 3, 'You stood in the fire!', 14, 0, 100, 0, 0, 24481, 'Majordomo Staghelm - Slay'),
(52571, 10, 0, 'My studies... had only just begun...', 14, 0, 100, 0, 0, 24471, 'Majordomo Staghelm to Player'),
(52571, 11, 0, 'Well, well. I admire your tenacity. Baleroc stood guard over this keep for a thousand mortal lifetimes.', 14, 0, 100, 0, 0, 24473, 'Majordomo Staghelm - Baleroc Outro 1'),
(52571, 12, 0, 'But none may enter the Firelord\'s abode!', 14, 0, 100, 0, 0, 24474, 'Majordomo Staghelm - Baleroc Outro'),
(52571, 13, 0, 'Beg for mercy now, and I may yet allow you to live. Well, \"heroes?\" What is your answer?', 14, 0, 100, 0, 0, 24475, 'Majordomo Staghelm - Baleroc Outro');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53231, 0, 0, '|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|tYou are about to burst into |cFFFF0000|Hspell:100460|h[Blazing Heat]|h|r!', 42, 0, 100, 0, 0, 0, 'Lava Scion - Announce Blazing Heat');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53375, 0, 0, 'None escape the rage of the Firelands!', 14, 0, 100, 0, 0, 24813, 'Herald of the Burning End');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53494, 0, 0, 'You are forbidden from my master\'s domain, mortals.', 14, 0, 100, 0, 0, 24441, 'Baleroc'),
(53494, 1, 0, 'Fool mortals. Hurl yourselves into your own demise!', 14, 0, 100, 0, 0, 24446, 'Baleroc'),
(53494, 2, 0, 'Burn beneath my molten fury!', 14, 0, 100, 0, 0, 24459, 'Baleroc'),
(53494, 3, 0, 'By the Firelord\'s command, you, too, shall perish!', 14, 0, 100, 0, 0, 24447, 'Baleroc'),
(53494, 4, 0, 'None shall pass!', 14, 0, 100, 0, 0, 24452, 'Baleroc'),
(53494, 4, 1, 'You have been judged.', 14, 0, 100, 0, 0, 24449, 'Baleroc'),
(53494, 4, 2, 'Behold your weakness.', 14, 0, 100, 0, 0, 24451, 'Baleroc'),
(53494, 5, 0, 'Your flesh is forfeit to the fires of this realm.', 14, 0, 100, 0, 0, 24450, 'Baleroc'),
(53494, 6, 0, '%s goes into a berserker rage!', 16, 0, 100, 0, 0, 0, 'Baleroc'),
(53494, 7, 0, 'Mortal filth... the master\'s keep is forbidden....', 14, 0, 100, 0, 0, 24444, 'Baleroc'),
(53494, 8, 0, '|TInterface\\Icons\\inv_sword_09.blp:20|t%s readies his |cFFFF0000Inferno Blade|r!', 41, 0, 100, 0, 0, 0, 'Baleroc'),
(53494, 9, 0, '|TInterface\\Icons\\spell_shadow_curse:20|t%s readies his |cFF551A8BDecimation Blade|r!', 41, 0, 100, 0, 0, 0, 'Baleroc');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53691, 0, 0, 'A-hah! The interlopers! Kill them. EAT THEM!', 14, 0, 0, 0, 0, 24565, 'Shannox aggro'),
(53691, 1, 0, 'Ohh... the pain.  Lord of Fire, it hurts....', 14, 0, 0, 0, 0, 24568, 'Shannox death'),
(53691, 2, 0, 'Fetch your supper!', 14, 0, 0, 0, 0, 24569, 'Shannox dog attack 05'),
(53691, 3, 0, 'Go for the throat!', 14, 0, 0, 0, 0, 24573, 'Shannox dog attack 01'),
(53691, 4, 0, 'Riplimb! No... no! Oh, you terrible little beasts! How could you?!', 14, 0, 0, 0, 0, 24574, 'Shannox dogdeath 01'),
(53691, 5, 0, 'Oh, you murderers! Why? Why would you kill such a noble animal?', 14, 0, 0, 0, 0, 24575, 'Shannox dogdeath 02'),
(53691, 6, 0, 'Now you burn!', 14, 0, 0, 0, 0, 24576, 'Shannox fireattack 01'),
(53691, 6, 1, 'Twist in flames, interlopers!', 14, 0, 0, 0, 0, 24577, 'Shannox fireattack 02'),
(53691, 7, 0, 'Dog food!', 14, 0, 0, 0, 0, 24578, 'Shannox kill 04'),
(53691, 7, 1, 'Now you stay dead!', 14, 0, 0, 0, 0, 24579, 'Shannox kill 03'),
(53691, 7, 2, 'The Firelord will be most pleased.', 14, 0, 0, 0, 0, 24580, 'Shannox kill 02'),
(53691, 8, 0, 'Yes, I smell them too, Riplimb. Outsiders encroach on the Firelord\'s private grounds. Find their trail. Find them for me, that I may dispense punishment!', 14, 0, 0, 0, 0, 24584, 'Shannox spawn');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53734, 0, 0, 'Together we call upon the lord of fire!', 14, 0, 100, 0, 0, 24800, 'Blazing Talon Clawshaper');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53772, 1, 0, 'I\'ll crush you underfoot!', 14, 0, 100, 0, 0, 24557, 'Lord Rhyolith - Concussive Stomp 1'),
(53772, 1, 1, 'Stomp now.', 14, 0, 100, 0, 0, 24556, 'Lord Rhyolith - Concussive Stomp 2'),
(53772, 2, 0, 'Broken. Mnngghhh... broken...', 14, 0, 100, 0, 0, 24545, 'Rhyolith death'),
(53772, 3, 0, 'Finished.', 14, 0, 100, 0, 0, 24546, 'Rhyolith kill 01'),
(53772, 3, 1, 'So soft!', 14, 0, 100, 0, 0, 24547, 'Rhyolith kill 02'),
(53772, 3, 2, 'Squeak, little pest.', 14, 0, 100, 0, 0, 24548, 'Rhyolith kill 03'),
(53772, 5, 0, 'Stomp now.', 14, 0, 100, 0, 0, 24556, 'Rhyolith stomp 1'),
(53772, 5, 1, 'I\'ll crush you underfoot!', 14, 0, 100, 0, 0, 24557, 'Rhyolith stomp 02'),
(53772, 6, 0, '%s stumbles as his armor is shattered!', 41, 0, 100, 0, 0, 0, 'Lord Rhyolith - Announce Armor Shattered'),
(53772, 7, 0, 'Eons I have slept undisturbed... Now this... Creatures of flesh, now you will BURN!', 14, 0, 100, 0, 0, 24558, 'Lord Rhyolith - Armor Shattered'),
(53772, 8, 0, 'Broken. Mnngghhh... broken...', 14, 0, 100, 0, 0, 24545, 'Lord Rhyolith - Death'),
(53772, 9, 0, 'Finished.', 14, 0, 100, 0, 0, 24546, 'Lord Rhyolith - Slay 1'),
(53772, 9, 1, 'So soft!', 14, 0, 100, 0, 0, 24547, 'Lord Rhyolith - Slay 2'),
(53772, 9, 2, 'Squeak, little pest.', 14, 0, 100, 0, 0, 24548, 'Lord Rhyolith - Slay 3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53872, 0, 0, 'No, fiend. Your time is NOW.', 14, 0, 100, 0, 0, 25159, 'Cenarius'),
(53872, 1, 0, 'Perhaps...', 14, 0, 100, 0, 0, 25160, 'Cenarius'),
(53872, 2, 0, 'Ragnaros has perished.  But the primal powers he represents can never be vanquished.  Another will rise to power, someday.', 14, 0, 100, 0, 0, 25158, 'Cenarius'),
(53872, 3, 0, 'Indeed.', 14, 0, 100, 0, 0, 25161, 'Cenarius');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53875, 0, 0, 'Heroes! He is bound. Finish him!', 14, 0, 100, 0, 0, 25169, 'Malfurion Stormrage '),
(53875, 1, 0, 'It is finished then!', 14, 0, 100, 0, 0, 25170, 'Malfurion Stormrage'),
(53875, 2, 0, 'Heroes, the world owes you a great debt.', 14, 0, 100, 0, 0, 25171, 'Malfurion Stormrage');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53876, 0, 0, 'Yes Cenarius, we must maintain a constant vigil over this realm.  But let us celebrate this day and the great victory we have earned here.', 14, 0, 100, 0, 0, 25168, 'Hamuul event 1'),
(53876, 1, 0, 'Yes Cenarius, we must maintain a constant vigil over this realm.  But let us celebrate this day and the great victory we have earned here.', 14, 0, 100, 0, 0, 25168, 'Archdruid Hamuul Runetotem to Player');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53896, 0, 0, 'Behold His power!', 14, 0, 100, 0, 0, 24809, 'Blazing Talon Initiate'),
(53896, 0, 1, 'Let the unbelievers perish in fire!', 14, 0, 100, 0, 0, 24799, 'Blazing Talon Initiate'),
(53896, 0, 2, 'We call upon you, Firelord!', 14, 0, 100, 0, 0, 24808, 'Blazing Talon Initiate'),
(53896, 0, 3, 'Witness the majesty of flame!', 14, 0, 100, 0, 0, 24811, 'Blazing Talon Initiate');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(54015, 0, 0, 'What have we here - visitors to our kingdom in the Firelands?', 14, 0, 100, 1, 0, 24466, ''),
(54015, 1, 0, 'You mortals may remember Alysra, who spirited me to freedom in Mount Hyjal. She, too has been reborn. Born of flame!', 14, 0, 100, 1, 0, 24467, ''),
(54015, 2, 0, 'I wish I could watch her reduce your pitiful band to cinders, but I am needed elsewhere. Farewell!', 14, 0, 100, 1, 0, 24468, '');
