INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53879, 0, 0, '%s feels players on his left side.\nHe\'s about to roll left!', 41, 0, 100, 0, 0, 0, 'Spine of Deathwing - left roll preparation'),
(53879, 1, 0, '%s feels players on his right side.\nHe\'s about to roll right!', 41, 0, 100, 0, 0, 0, 'Spine of Deathwing - right roll preparation'),
(53879, 2, 0, '%s rolls left!', 41, 0, 100, 0, 0, 0, 'Spine of Deathwing - left roll'),
(53879, 3, 0, '%s rolls right!', 41, 0, 100, 0, 0, 0, 'Spine of Deathwing - right roll'),
(53879, 4, 0, 'Your tenacity is admirable, but pointless. You ride into the jaws of the apocalypse.', 14, 0, 100, 0, 0, 26346, 'Spine of Deathwing - backevent 01'),
(53879, 4, 1, 'You are less than dust, fit only to be brushed from my back.', 14, 0, 100, 0, 0, 26350, 'Spine of Deathwing - slay 01'),
(53879, 4, 2, 'Ha! I had not realized you fools were still there.', 14, 0, 100, 0, 0, 26351, 'Spine of Deathwing - slay 02'),
(53879, 4, 3, 'Your efforts are insignificant. I carry you to your deaths.', 14, 0, 100, 0, 0, 26352, 'Spine of Deathwing - slay 03');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(53890, 0, 0, '|TInterface\\Icons\\inv_gizmo_supersappercharge.blp:20|t%s is casting |c0087CEFA|Hspell:105845|h[Nuclear Blast]|h|r!', 41, 0, 100, 0, 0, 0, 'Blackhorn - skyfire low hp');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55265, 0, 0, 'You seek to halt an avalanche. I will bury you.', 14, 0, 100, 0, 0, 26268, 'morchok aggro'),
(55265, 1, 0, 'Impossible. This cannot be. The tower... must... fall...', 14, 0, 100, 0, 0, 26269, 'morchok death'),
(55265, 2, 0, 'Cowards. Weaklings. Come down and fight, or I will bring you down.', 14, 0, 100, 0, 0, 26270, 'morchok event 1'),
(55265, 3, 0, 'You cannot hide in this temple forever, Shaman.', 14, 0, 100, 0, 0, 26271, 'morchok event 2'),
(55265, 4, 0, 'I will turn this tower to rubble, and scatter it across the wastes.', 14, 0, 100, 0, 0, 26272, 'morchok event 3'),
(55265, 5, 0, 'Wyrmrest will fall. All will be dust.', 14, 0, 100, 0, 0, 26273, 'morchok event 4'),
(55265, 6, 0, 'The stone calls...', 14, 0, 100, 0, 0, 26274, 'morchok ground 1 1'),
(55265, 6, 1, 'The ground shakes...', 14, 0, 100, 0, 0, 26275, 'morchok ground 1 2'),
(55265, 6, 2, 'The rocks tremble...', 14, 0, 100, 0, 0, 26276, 'morchok ground 1 3'),
(55265, 6, 3, 'The surface quakes...', 14, 0, 100, 0, 0, 26277, 'morchok ground 1 4'),
(55265, 7, 0, '...and the black blood of the earth consumes you.', 14, 0, 100, 0, 0, 26278, 'morchok ground 2 1'),
(55265, 7, 1, '...and there is no escape from the Old Gods.', 14, 0, 100, 0, 0, 26279, 'morchok ground 2 2'),
(55265, 7, 2, '...and the rage of the true gods follows.', 14, 0, 100, 0, 0, 26280, 'morchok ground 2 3'),
(55265, 7, 3, '...and you drown in the hate of The Master.', 14, 0, 100, 0, 0, 26281, 'morchok ground 2 4'),
(55265, 8, 0, 'No mortal shall turn me from my task.', 14, 0, 100, 0, 0, 26282, 'morchok intro'),
(55265, 9, 0, 'Flee, and die.', 14, 0, 100, 0, 0, 26283, 'morchok orb 1'),
(55265, 9, 1, 'Run, and perish.', 14, 0, 100, 0, 0, 26284, 'morchok orb 2'),
(55265, 10, 0, 'I am unstoppable.', 14, 0, 100, 0, 0, 26285, 'morchok slay 1'),
(55265, 10, 1, 'It was inevitable.', 14, 0, 100, 0, 0, 26286, 'morchok slay 2'),
(55265, 10, 2, 'Ground to dust.', 14, 0, 100, 0, 0, 26287, 'morchok slay 3'),
(55265, 11, 0, 'You thought to fight me alone? The earth splits to swallow and crush you.', 14, 0, 100, 0, 0, 26288, 'morchok split'),
(55265, 12, 0, '%s summons a Resonating Crystal!', 41, 0, 100, 0, 0, 0, 'Morchok - summon crystall');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55294, 0, 0, 'Now is the hour of twilight!', 14, 0, 100, 0, 0, 26314, 'Ultraxion aggro'),
(55294, 1, 0, 'I WILL DRAG YOU WITH ME INTO FLAME AND DARKNESS!', 14, 0, 100, 0, 0, 26315, 'Ultraxion berserk'),
(55294, 2, 0, 'But...but...I am...Ul...trax...ionnnnnn...', 14, 0, 100, 0, 0, 26316, 'Ultraxion death'),
(55294, 3, 0, 'I am the beginning of the end...the shadow which blots out the sun...the bell which tolls your doom...', 14, 0, 100, 0, 0, 26317, 'Ultraxion intro 01'),
(55294, 4, 0, 'For this moment ALONE was I made. Look upon your death, mortals, and despair!', 14, 0, 100, 0, 0, 26318, 'Ultraxion intro 02'),
(55294, 5, 0, 'Fall before Ultraxion!', 14, 0, 100, 0, 0, 26319, 'Ultraxion slay 01'),
(55294, 5, 1, 'You have no hope!', 14, 0, 100, 0, 0, 26320, 'Ultraxion slay 02'),
(55294, 5, 2, 'Hahahahaha!', 14, 0, 100, 0, 0, 26321, 'Ultraxion slay 03'),
(55294, 6, 0, 'The final shred of light fades, and with it, your pitiful mortal existence!', 14, 0, 100, 0, 0, 26323, 'Ultraxion spell 01'),
(55294, 7, 0, 'Through the pain and fire my hatred burns!', 14, 0, 100, 0, 0, 26325, 'Ultraxion spell 03'),
(55294, 8, 0, 'A monstrous force pulls you into the twilight realm!', 41, 0, 100, 0, 0, 0, 'Ultraxion announce'),
(55294, 9, 0, '|TInterface\\Icons\\spell_shadow_twilight.blp:20|t Ultraxion begins casting |cFF9900CC|Hspell:106371|h[Hour of Twilight]|h|r!', 41, 0, 100, 0, 0, 0, 'Ultraxion - announce hour of twilight'),
(55294, 10, 0, '|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t Ultraxion becomes |cFF9900CC|Hspell:106373|h[More Unstable]|h|r!', 41, 0, 100, 0, 0, 0, 'Ultraxion - announce unstability');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55308, 0, 0, 'Once more shall the twisted flesh-banners of N\'Zoth chitter and howl above the fly-blown corpse of this world. After millennia, we have returned.', 14, 0, 100, 0, 0, 26335, 'zonozz aggro'),
(55308, 1, 0, 'Uovssh thyzz... qwaz...', 14, 0, 100, 0, 0, 26336, 'zonozz death'),
(55308, 2, 0, 'Vwyq agth sshoq\'meg N\'Zoth vra zz shfk qwor ga\'halahs agthu. Uulg\'ma, ag qam.', 14, 0, 100, 0, 0, 26337, 'zonozz intro'),
(55308, 3, 0, 'Sk\'tek agth nuq N\'Zoth yyqzz.', 14, 0, 100, 0, 0, 26338, 'zonozz slay 1'),
(55308, 3, 1, 'Sk\'yahf agth huqth N\'Zoth qornaus.', 14, 0, 100, 0, 0, 26339, 'zonozz slay 2'),
(55308, 3, 2, 'Sk\'shuul agth vorzz N\'Zoth naggwa\'fssh.', 14, 0, 100, 0, 0, 26341, 'zonozz slay 3'),
(55308, 4, 0, 'Sk\'magg yawifk hoq.', 14, 0, 100, 0, 0, 26340, 'zonozz spell 1'),
(55308, 4, 1, 'Sk\'uuyat guulphg hoq.', 14, 0, 100, 0, 0, 26342, 'zonozz spell 2'),
(55308, 4, 2, 'Sk\'shgn eqnizz hoq.', 14, 0, 100, 0, 0, 26343, 'zonozz spell 3'),
(55308, 5, 0, 'N\'Zoth ga zyqtahg iilth.', 14, 0, 100, 0, 0, 26344, 'zonozz spell 4'),
(55308, 6, 0, 'Gul\'kafh an\'qov N\'Zoth.', 14, 0, 100, 0, 0, 26345, 'zonozz spell 5'),
(55308, 7, 0, 'Victory for Deathwing. For the glory of N\'Zoth!', 42, 0, 100, 0, 0, 0, 'zonozz aggro whisper'),
(55308, 8, 0, 'To have waited so long... for this...', 42, 0, 100, 0, 0, 0, 'zonozz death whisper'),
(55308, 9, 0, 'Once more shall the twisted flesh-banners of N\'Zoth chitter and howl above the fly-blown corpse of this world. After millennia, we have returned.', 42, 0, 100, 0, 0, 26335, 'zonozz intro whisper'),
(55308, 10, 0, 'Your souls shall sate N\'Zoth\'s endless hunger.', 42, 0, 100, 0, 0, 0, 'zonozz slay 1 whisper'),
(55308, 10, 1, 'Your deaths shall sing of N\'Zoth\'s unending glory.', 42, 0, 100, 0, 0, 0, 'zonozz slay 2 whisper'),
(55308, 10, 2, 'Your skulls shall adorn N\'Zoth\'s writhing throne.', 42, 0, 100, 0, 0, 0, 'zonozz slay 3 whisper'),
(55308, 11, 0, 'Your fear drives me.', 42, 0, 100, 0, 0, 0, 'zonozz spell 1 whisper'),
(55308, 11, 1, 'Your suffering strengthens me.', 42, 0, 100, 0, 0, 0, 'zonozz spell 2 whisper'),
(55308, 11, 2, 'Your agony sustains me.', 42, 0, 100, 0, 0, 0, 'zonozz spell 3 whisper'),
(55308, 12, 0, 'The will of N\'Zoth corrupts you.', 42, 0, 100, 0, 0, 0, 'zonozz spell 4 whisper'),
(55308, 13, 0, 'Gaze into the heart of N\'Zoth.', 42, 0, 100, 0, 0, 0, 'zonozz spell 5 whisper');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55312, 0, 0, 'Iilth qi\'uothk shn\'ma yeh\'glu Shath\'Yar! H\'IWN IILTH!', 14, 0, 100, 0, 0, 26326, 'yor\'sahj aggro'),
(55312, 1, 0, 'Ez, Shuul\'wah! Sk\'woth\'gl yu\'gaz yoh\'ghyl iilth!', 14, 0, 100, 0, 0, 26327, 'yor\'sahj death'),
(55312, 2, 0, 'Ak\'agthshi ma uhnish, ak\'uq shg\'cul vwahuhn! H\'iwn iggksh Phquathi gag OOU KAAXTH SHUUL!', 14, 0, 100, 0, 0, 26328, 'yor\'sahj intro'),
(55312, 3, 0, 'Sk\'yahf qi\'plahf PH\'MAGG!', 14, 0, 100, 0, 0, 26329, 'yor\'sahj slay 1'),
(55312, 3, 1, 'H\'iwn zaix Shuul\'wah, PHQUATHI!', 14, 0, 100, 0, 0, 26330, 'yor\'sahj slay 2'),
(55312, 3, 2, 'Shkul an\'zig qvsakf KSSH\'GA, ag\'THYZAK agthu!', 14, 0, 100, 0, 0, 26331, 'yor\'sahj slay 3'),
(55312, 4, 0, 'KYTH ag\'xig yyg\'far IIQAATH ONGG!', 14, 0, 100, 0, 0, 26332, 'yor\'sahj spell 1'),
(55312, 4, 1, 'UULL lwhuk H\'IWN!', 14, 0, 100, 0, 0, 26333, 'yor\'sahj spell 2'),
(55312, 5, 0, 'You will drown in the blood of the Old Gods! ALL OF YOU!', 42, 0, 100, 0, 0, 0, 'yor\'sahj aggro whisper'),
(55312, 6, 0, 'O, Deathwing! Your faithful servant has failed you!', 42, 0, 100, 0, 0, 0, 'yor\'sahj death whisper'),
(55312, 7, 0, 'Our numbers are endless, our power beyond reckoning! All who oppose the Destroyer will DIE A THOUSAND DEATHS!', 42, 0, 100, 0, 0, 0, 'yor\'sahj intro whisper'),
(55312, 8, 0, 'Your soul will know ENDLESS TORMENT!', 42, 0, 100, 0, 0, 0, 'yor\'sahj slay 1 whisper'),
(55312, 8, 1, 'All praise Deathwing, THE DESTROYER!', 42, 0, 100, 0, 0, 0, 'yor\'sahj slay 2 whisper'),
(55312, 8, 2, 'From its BLEAKEST DEPTHS, we RECLAIM this world!', 42, 0, 100, 0, 0, 0, 'yor\'sahj slay 3 whisper'),
(55312, 9, 0, 'SEE how we pour from the CURSED EARTH!', 42, 0, 100, 0, 0, 0, 'yor\'sahj spell 1 whisper'),
(55312, 9, 1, 'The DARKNESS devours ALL!', 42, 0, 100, 0, 0, 0, 'yor\'sahj spell 2 whisper'),
(55312, 10, 0, '%s calls upon the |cFF0080FF|Hspell:104900|h[Blue]|h|r, |cFF424242|Hspell:104894|h[Black]|h|r, and |cFFFFA901|Hspell:104901|h[Yellow]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 1 normal'),
(55312, 11, 0, '%s calls upon the |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFF088A08|Hspell:104898|h[Green]|h|r, and |cFF0080FF|Hspell:104900|h[Blue]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 2 normal'),
(55312, 12, 0, '%s calls upon the |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFFFF0404|Hspell:104897|h[Red]|h|r, and |cFF424242|Hspell:104894|h[Black]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 3 normal'),
(55312, 13, 0, '%s calls upon the |cFF088A08|Hspell:104898|h[Green]|h|r, |cFFFFA901|Hspell:104901|h[Yellow]|h|r, and |cFFFF0404|Hspell:104897|h[Red]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 4 normal'),
(55312, 14, 0, '%s calls upon the |cFF088A08|Hspell:104898|h[Green]|h|r, |cFFFF0404|Hspell:104897|h[Red]|h|r, and |cFF424242|Hspell:104894|h[Black]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 5 normal'),
(55312, 15, 0, '%s calls upon the |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFF0080FF|Hspell:104900|h[Blue]|h|r, and |cFFFFA901|Hspell:104901|h[Yellow]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 6 normal'),
(55312, 16, 0, '%s calls upon the |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFFFF0404|Hspell:104897|h[Red]|h|r, |cFFFFA901|Hspell:104901|h[Yellow]|h|r, and |cFF424242|Hspell:104894|h[Black]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 1 heroic'),
(55312, 17, 0, '%s calls upon the |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFF088A08|Hspell:104898|h[Green]|h|r, |cFF424242|Hspell:104894|h[Black]|h|r, and |cFF0080FF|Hspell:104900|h[Blue]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 2 heroic'),
(55312, 18, 0, '%s calls upon the |cFF0080FF|Hspell:104900|h[Blue]|h|r, |cFF9932CD|Hspell:104896|h[Purple]|h|r, |cFF088A08|Hspell:104898|h[Green]|h|r, and |cFFFFA901|Hspell:104901|h[Yellow]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 3 heroic'),
(55312, 19, 0, '%s calls upon the |cFF0080FF|Hspell:104900|h[Blue]|h|r, |cFF424242|Hspell:104894|h[Black]|h|r, |cFF9932CD|Hspell:104896|h[Purple]|h|r, and |cFFFFA901|Hspell:104901|h[Yellow]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 4 heroic'),
(55312, 20, 0, '%s calls upon the |cFF088A08|Hspell:104898|h[Green]|h|r, |cFFFF0404|Hspell:104897|h[Red]|h|r, |cFF0080FF|Hspell:104900|h[Blue]|h|r, and |cFF424242|Hspell:104894|h[Black]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 5 heroic'),
(55312, 21, 0, '%s calls upon the |cFF088A08|Hspell:104898|h[Green]|h|r, |cFFFFA901|Hspell:104901|h[Yellow]|h|r, |cFF424242|Hspell:104894|h[Black]|h|r, and |cFFFF0404|Hspell:104897|h[Red]|h|r Bloods of Shu\'ma!', 41, 0, 100, 0, 0, 0, 'Yor\'sahj - summon globue 6 heroic');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55689, 0, 0, 'Even with the Aspect of Time on your side, you stumble foolishly into a trap?', 14, 0, 100, 0, 0, 26223, 'hagara adds 1'),
(55689, 1, 0, 'Don\'t preen just yet, little pups. We\'ll cleanse this world of your kind.', 14, 0, 100, 0, 0, 26224, 'hagara adds 2'),
(55689, 2, 0, 'You\'ll not leave this place alive!', 14, 0, 100, 0, 0, 26225, 'hagara adds 3'),
(55689, 3, 0, 'Not one of you will live to see the final cataclysm! Finish them!', 14, 0, 100, 0, 0, 26226, 'hagara adds 4'),
(55689, 4, 0, 'You cross the Stormbinder! I\'ll slaughter you all.', 14, 0, 100, 0, 0, 26227, 'hagara aggro'),
(55689, 5, 0, 'What are you doing?', 14, 0, 100, 0, 0, 26228, 'hagara circuit 01'),
(55689, 5, 1, 'You\'re toying with death.', 14, 0, 100, 0, 0, 26229, 'hagara circuit 02'),
(55689, 5, 2, 'You think you can play with my lightning?', 14, 0, 100, 0, 0, 26230, 'hagara circuit 03'),
(55689, 5, 3, 'Enough of your games! You won\'t live to do it again.', 14, 0, 100, 0, 0, 26232, 'hagara circuit 05'),
(55689, 5, 4, 'No! More... lightning...', 14, 0, 100, 0, 0, 26233, 'hagara circuit 06'),
(55689, 5, 5, 'I\'ll finish you now, pups!', 14, 0, 100, 0, 0, 26234, 'hagara circuit 07'),
(55689, 6, 0, 'Get away from that, mongrel!', 14, 0, 100, 0, 0, 26235, 'hagara crystal dead 01'),
(55689, 6, 1, 'You\'ll PAY for that.', 14, 0, 100, 0, 0, 26236, 'hagara crystal dead 02'),
(55689, 6, 2, 'Enough!', 14, 0, 100, 0, 0, 26237, 'hagara crystal dead 03'),
(55689, 6, 3, 'Again?!', 14, 0, 100, 0, 0, 26239, 'hagara crystal dead 05'),
(55689, 6, 4, 'Impudent pup!', 14, 0, 100, 0, 0, 26240, 'hagara crystal dead 06'),
(55689, 6, 5, 'The one remaining is still enough to finish you.', 14, 0, 100, 0, 0, 26241, 'hagara crystal dead 07'),
(55689, 7, 0, 'Cowards! You pack of weakling... dogs...', 14, 0, 100, 0, 0, 26243, 'hagara dead'),
(55689, 8, 0, 'You face more than my axes, this close.', 14, 0, 100, 0, 0, 26244, 'hagara frostray 01'),
(55689, 8, 1, 'See what becomes of those who stand before me!', 14, 0, 100, 0, 0, 26245, 'hagara frostray 02'),
(55689, 8, 2, 'Feel a chill up your spine...?', 14, 0, 100, 0, 0, 26246, 'hagara frostray 03'),
(55689, 9, 0, 'You can\'t outrun the storm.', 14, 0, 100, 0, 0, 26247, 'hagara glacier 01'),
(55689, 9, 1, 'Die beneath the ice.', 14, 0, 100, 0, 0, 26248, 'hagara glacier 02'),
(55689, 10, 0, 'Stay, pup.', 14, 0, 100, 0, 0, 26249, 'hagara icetomb 01'),
(55689, 10, 1, 'Hold still.', 14, 0, 100, 0, 0, 26250, 'hagara icetomb 02'),
(55689, 11, 0, 'Swagger all you like; you pups don\'t stand a chance. Flee now, while you can.', 14, 0, 100, 0, 0, 26251, 'hagara intro 01'),
(55689, 12, 0, 'Suffer the storm\'s wrath!', 14, 0, 100, 0, 0, 26252, 'hagara lightning 01'),
(55689, 12, 1, 'Thunder and lightning dance at my call!', 14, 0, 100, 0, 0, 26253, 'hagara lightning 02'),
(55689, 13, 0, 'Feh!', 14, 0, 100, 0, 0, 26254, 'hagara slay 02'),
(55689, 13, 1, 'You should have run, dog.', 14, 0, 100, 0, 0, 26255, 'hagara slay 01'),
(55689, 13, 2, 'Down, pup.', 14, 0, 100, 0, 0, 26256, 'hagara slay 03'),
(55689, 13, 3, 'A waste of my time.', 14, 0, 100, 0, 0, 26257, 'hagara slay 04');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55870, 0, 0, 'Little hand says it\'s time to rock and roll. Everyone into the hold: We\'ve got a dragon to kill.', 14, 0, 100, 0, 0, 26289, 'Sky Captain Swayze blackhorn victory'),
(55870, 1, 0, 'The plates! He\'s coming apart! Tear up the plates and we\'ve got a shot at bringing him down!', 14, 0, 100, 0, 0, 26290, 'Sky Captain Swayze deathwing back 01'),
(55870, 2, 0, 'Don\'t worry about me. Stop the Destroyer! Enshu-falah-nah, dorini.', 14, 0, 100, 0, 0, 26291, 'Sky Captain Swayze'),
(55870, 3, 0, 'All ahead full. Everything depends on our speed! We can\'t let the Destroyer get away.', 14, 0, 100, 0, 0, 26292, 'Sky Captain Swayze event 01'),
(55870, 4, 0, 'All hands to battle stations; get those monsters away from the ship!', 14, 0, 100, 0, 0, 26294, 'Sky Captain Swayze event 02'),
(55870, 5, 0, 'Concentrate everything on the armored drake!', 14, 0, 100, 0, 0, 26295, 'Sky Captain Swayze event 03'),
(55870, 6, 0, 'An enemy sapper\'s breached the engine room!', 14, 0, 100, 0, 0, 26296, 'Sky Captain Swayze event 04'),
(55870, 7, 0, 'The Skyfire can\'t take much more of this!', 14, 0, 100, 0, 0, 26297, 'Sky Captain Swayze event 05'),
(55870, 8, 0, 'We\'re going down. Abandon the ship!', 14, 0, 100, 0, 0, 26298, 'Sky Captain Swayze event 06'),
(55870, 9, 0, 'Welcome aboard the Skyfire.  You ready to chase down the end of the world?', 14, 0, 100, 0, 0, 26302, 'Sky Captain Swayze pre deathwing back 01'),
(55870, 10, 0, 'Our engines are damaged!  We\'re sitting ducks up here!', 14, 0, 100, 0, 0, 26303, 'Sky Captain Swayze pre deathwing back 02');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(55971, 0, 0, 'It is good to see you again, Alexstrasza. I have been busy in my absence.', 14, 0, 100, 0, 0, 26360, ''),
(55971, 1, 0, 'Twisting your pitiful whelps into mindless abominations, bent only to my will. It was a very... painful process.', 14, 0, 100, 0, 0, 26361, ''),
(55971, 2, 0, 'Mere whelps, experiments, a means to a greater end. You will see what the research of my clutch has yielded.', 14, 0, 100, 0, 0, 26362, ''),
(55971, 3, 0, 'Nefarian, Onyxia, Sinestra... they were nothing. Now you face my ultimate creation.', 14, 0, 100, 0, 0, 26363, ''),
(55971, 4, 0, 'The Hour of Twilight is nigh; the sun sets on your pitiful mortal existence.', 14, 0, 100, 0, 0, 26364, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56099, 0, 0, 'I will cleanse whatever corruption I can; my fire will not harm you.', 14, 0, 100, 0, 0, 26498, 'Alexstrasza - Introduce Ability'),
(56099, 1, 0, 'No! Such power! Deathwing\'s summoning of the final Cataclysm will destroy all life on Azeroth. Quickly, we must interrupt him!', 14, 0, 100, 0, 0, 26500, 'Alexstrasza - Cataclysm'),
(56099, 2, 0, 'He\'s completely mad!!', 14, 0, 100, 0, 0, 26499, 'Alexstrasza - Phase 2'),
(56099, 3, 0, 'Excellent work. The fire of my heart glows with a brilliant purity unmatched; every spark of it I will channel into the Dragon Soul.', 14, 0, 100, 0, 0, 26497, 'Alexstrasza - Charge Dragon Soul'),
(56099, 4, 0, 'He\'s completely mad!', 14, 0, 100, 0, 0, 26499, 'Alexstrasza - second phase'),
(56099, 5, 0, 'Excellent work. The fire of my heart glows with a brilliant purity unmatched; every spark of it I will channel into the Dragon Soul.', 14, 0, 100, 0, 0, 26497, 'Alexstrasza - outro');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56100, 0, 0, 'I will bring you closer to the Emerald Dream. Seek safety there when the fight becomes too intense.', 14, 0, 100, 0, 0, 26142, 'Ysera - Introduce Ability'),
(56100, 1, 0, 'Deathwing is conjuring the final Cataclysm; even the Emerald Dream trembles. If we are to stop the spell, we must attack him together.', 14, 0, 100, 0, 0, 26144, 'Ysera - Cataclysm'),
(56100, 2, 0, 'Such rage I have never seen...', 14, 0, 100, 0, 0, 26143, 'Ysera - Phase 2'),
(56100, 3, 0, 'We are one step closer. The unknowable, transcendent power of the Emerald Dream I now give unto the Dragon Soul.', 14, 0, 100, 0, 0, 26141, 'Ysera - Charge Dragon Soul');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56101, 0, 0, 'I will charge you with arcane energy to blast your foes.', 14, 0, 100, 0, 0, 26259, 'Kalecgos - Introduce Ability'),
(56101, 1, 0, 'The Destroyer is gathering all his might for a blow that will split the world. Attack him, now! We must stop the final Cataclysm!', 14, 0, 100, 0, 0, 26261, 'Kalecgos - Cataclysm'),
(56101, 2, 0, 'Is he... coming apart?', 14, 0, 100, 0, 0, 26260, 'Kalecgos - Phase 2'),
(56101, 3, 0, 'Well done! I will realign the flow of mana and fill the Dragon Soul with all my arcane might.', 14, 0, 100, 0, 0, 26258, 'Kalecgos - Charge Dragon Soul');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56102, 0, 0, 'I will slow the Destroyer\'s attacks when I can.', 14, 0, 100, 0, 0, 25949, 'Nozdormu - Introduce Ability'),
(56102, 1, 0, 'Hurry, heroes. In mere moments Deathwing\'s Cataclysm will complete what he begun and end the world. Join me in the attack, now!', 14, 0, 100, 0, 0, 25951, 'Nozdormu - Cataclysm'),
(56102, 2, 0, 'Press the attack, heroes.', 14, 0, 100, 0, 0, 25950, 'Nozdormu - Phase 2'),
(56102, 3, 0, 'It is time. I will expend everything to bind every thread here, now, around the Dragon Soul. What comes to pass will NEVER be undone.', 14, 0, 100, 0, 0, 26600, 'Nozdormu - Charge Dragon Soul'),
(56102, 4, 0, 'It is time. I will expend everything to bind every thread here, now, around the Dragon Soul. What comes to pass will NEVER be undone.', 14, 0, 100, 0, 0, 25948, 'Nozdormu - outro');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56103, 0, 0, 'It is done; at last the Destroyer has met his end. Now, we can begin to heal our world.', 14, 0, 100, 0, 0, 25901, 'Thrall - Pre Fight'),
(56103, 1, 0, 'Aspects! Aid the heroes as best you can.', 14, 0, 100, 0, 0, 25895, 'Thrall - Saay Phase Two'),
(56103, 1, 1, 'Avenge the fallen! Continue the fight!', 14, 0, 100, 0, 0, 25903, 'Thrall - second phase 2'),
(56103, 1, 2, 'These champions are our only hope for exposing Deathwing\'s weakness. Together, we can prevail.', 14, 0, 100, 0, 0, 25896, 'Thrall - second phase 3'),
(56103, 1, 3, 'Don\'t give up! We are counting on you to push Deathwing back.', 14, 0, 100, 0, 0, 25897, 'Thrall - second phase 4'),
(56103, 1, 4, 'Only you can give us our opening!', 14, 0, 100, 0, 0, 25902, 'Thrall - second phase 5');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56165, 0, 0, 'A conducting crystal overloads!', 41, 0, 100, 0, 0, 0, 'Crystal Conductor - announce overload');
