(56167, 0, 0, '|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|tThe %s is injured and sprouts |cFFFE9A2EBlistering Tentacles|r!', 41, 0, 100, 0, 0, 0, 'Limbt Tentacle - Announce Blistering Tentacles'),
(56167, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s begins to |cFFFF0000|Hspell:105863|h[Hemorrhage]|h|r!', 41, 0, 100, 0, 0, 0, 'Madness of Deathwing - Hemorrhage');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56168, 0, 0, '|TInterface\\Icons\\ability_warrior_bloodnova.blp:20|tThe %s is injured and sprouts |cFFFE9A2EBlistering Tentacles|r!', 41, 0, 100, 0, 0, 0, 'Limbt Tentacle - Announce Blistering Tentacles'),
(56168, 10, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s begins to |cFFFF0000|Hspell:105863|h[Hemorrhage]|h|r!', 41, 0, 100, 0, 0, 0, 'Madness of Deathwing - Hemorrhage');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56173, 0, 0, 'You have done NOTHING. I will tear your world APART.', 14, 0, 100, 0, 0, 26527, 'Deathwing - Aggro'),
(56173, 1, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s begins to cast |cFFFF0000|Hspell:107018|h[Assault Aspects]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Assault Aspects'),
(56173, 2, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFF04FC32|Hspell:107018|h[Ysera]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Assault Ysera'),
(56173, 2, 1, 'Your armor means nothing, your faith even less.', 14, 0, 100, 0, 0, 26355, 'Madness of Deathwing - arrow 2'),
(56173, 2, 2, 'The sea will swallow your smoldering remains.', 14, 0, 100, 0, 0, 26356, 'Madness of Deathwing - arrow 3'),
(56173, 3, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFF5858FA|Hspell:107018|h[Kalecgos]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Assault Kalecgos'),
(56173, 4, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFFFFFF00|Hspell:107018|h[Nozdormu]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Assault Nozdormu'),
(56173, 5, 0, '|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFFFF0000|Hspell:107018|h[Alexstrasza]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Assault Alexstrasza'),
(56173, 6, 0, '|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s begins to cast |cFFFF0000|Hspell:106523|h[Cataclysm]|h|r! Stop Him!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Cataclysm'),
(56173, 7, 0, '|TInterface\\Icons\\spell_fire_moltenblood.blp:20|t%s begins to |cFFFF0000|Hspell:105863|h[Hemorrhage]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Hemorrhage'),
(56173, 8, 0, '|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s begins to cast |cFFFF0000|Hspell:105651|h[Elementium Bolt]|h|r!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Elementium Bolt'),
(56173, 9, 0, 'There is no shelter from my fury!', 14, 0, 100, 0, 0, 26354, 'Deathwing - Elementium Bolt 1'),
(56173, 9, 1, 'The sea will swallow your smoldering remains.', 14, 0, 100, 0, 0, 26356, 'Deathwing - Elementium Bolt 2'),
(56173, 9, 2, 'Your armor means nothing, your faith even less.', 14, 0, 100, 0, 0, 26355, 'Deathwing - Elementium Bolt 3'),
(56173, 10, 0, 'I AM DEATHWING, THE DESTROYER, THE END OF ALL THINGS, INEVITABLE, INDOMITABLE; I AM THE CATACLYSM!', 14, 0, 100, 0, 0, 26348, 'Deathwing - Slump'),
(56173, 11, 0, '|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s falls forward, get to |cFF04FC32Ysera\'s|r platform!', 41, 0, 100, 0, 0, 0, 'Deathwing - Announce Slump'),
(56173, 12, 0, '|TInterface\\Icons\\inv_stave_2h_deathwingraiddw_d_01.blp:20|t%s falls forward, get to |cFF04FC32Ysera\'s|r platform!', 41, 0, 100, 0, 0, 0, 'Madness of Deathwing - second phase'),
(56173, 13, 0, '%s goes into a berserker rage!', 41, 0, 100, 0, 0, 0, 'Madness of Deathwing - enrage');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56427, 0, 0, 'You won\'t get near the Master. Dragonriders, attack!', 14, 0, 100, 0, 0, 26210, 'Warmaster Blackhorn aggro'),
(56427, 1, 0, 'Well... done, heh. But I wonder if you\'re good enough... to best him.', 14, 0, 100, 0, 0, 26211, 'Warmaster Blackhorn death'),
(56427, 2, 0, 'Looks like I\'m doing this myself. Good!', 14, 0, 100, 0, 0, 26212, 'Warmaster Blackhorn event 01'),
(56427, 3, 0, 'We\'re flying a little too close. It\'s been a good fight, but I\'m ending it, now.', 14, 0, 100, 0, 0, 26213, 'Warmaster Blackhorn event 02'),
(56427, 4, 0, 'Hah! I was hoping you\'d make it this far. You\'d best be ready for a real fight.', 14, 0, 100, 0, 0, 26214, 'Warmaster Blackhorn intro'),
(56427, 5, 0, 'Mess with the bull....', 14, 0, 100, 0, 0, 26215, 'Warmaster Blackhorn slay 01'),
(56427, 5, 1, 'Down you go!', 14, 0, 100, 0, 0, 26217, 'Warmaster Blackhorn slay 03'),
(56427, 5, 2, 'Get up! Oh... weakling!', 14, 0, 100, 0, 0, 26218, 'Warmaster Blackhorn slay 04'),
(56427, 6, 0, 'Goriona! Give them hell!', 14, 0, 100, 0, 0, 26219, 'Warmaster Blackhorn spell 01'),
(56427, 7, 0, 'How\'s THIS?', 14, 0, 100, 0, 0, 26221, 'Warmaster Blackhorn spell 03'),
(56427, 7, 1, 'COME ON!', 14, 0, 100, 0, 0, 26222, 'Warmaster Blackhorn spell 04'),
(56427, 8, 0, 'A drake swoops down to drop a Twilight Sapper onto the deck!', 41, 0, 100, 0, 0, 0, 'Warmaster Blackhorn sapper yell'),
(56427, 9, 0, '|Tinterface\\icons\\spell_fire_ragnaros_lavabolt.blp:0|tStructural damage to the Skyfire triggers a sudden |cFFFF0000|Hspell:110095|h[Deck Fire]|h|r!', 41, 0, 100, 0, 0, 0, 'Blackhorn - skyfire low hp');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56664, 0, 0, 'Not necessarily. I believe...yes...it just might work.', 12, 0, 100, 5, 0, 26547, 'kalecgos open portal 1'),
(56664, 1, 0, 'The Focusing Iris within the Eye of Eternity may allow us to converge the magical matrix contained within the Dragon Soul.', 12, 0, 100, 5, 0, 26265, 'kalecgos open portal 2'),
(56664, 2, 0, 'Then I will open the way into the Eye of Eternity. You must not fail, heroes. The future of Azeroth hinges on your actions.', 12, 0, 100, 1, 0, 26266, 'kalecgos open portal 3'),
(56664, 3, 0, 'Excellent! We will begin the ritual at once!', 12, 0, 100, 5, 0, 26262, 'kalecgos - event'),
(56664, 4, 0, 'Winds of the arcane be at their backs, and refresh them in this hour of darkness!', 14, 0, 100, 0, 0, 26267, 'kalecgos - help'),
(56664, 5, 0, '|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t Kalecgos summons forth the |cFF0000FF|Hspell:105903|h[Source of Magic]|h|r!', 41, 0, 100, 0, 0, 0, 'Kalecgos - Source of Magic');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56667, 0, 0, 'It is no use, the power of the Soul is too great. I cannot wield it safely; the raging forces within it may be the doom of us all.', 12, 0, 100, 1, 0, 25904, 'thrall open portal 1'),
(56667, 1, 0, 'Yes, I see.  We can finally turn Deathwing\'s own power back against him.', 12, 0, 100, 1, 0, 25905, 'thrall open portal 2'),
(56667, 2, 0, 'We have no choice.  We must have faith in our allies.', 12, 0, 100, 1, 0, 25906, 'thrall open portal 2'),
(56667, 3, 0, 'Heroes, this burden falls to you once again.', 12, 0, 100, 1, 0, 25898, 'thrall - event 1'),
(56667, 4, 0, 'You must protect us from Deathwing\'s forces while we imbue the Dragon Soul with the power of the Aspects.', 12, 0, 100, 0, 0, 25899, 'thrall - event 2'),
(56667, 5, 0, 'Speak to me when you are ready to begin.', 12, 0, 100, 0, 0, 25900, 'thrall - event 3'),
(56667, 6, 0, 'Strength of the Earth, hear my call! Shield them in this dark hour, the last defenders of Azeroth!', 14, 0, 100, 0, 0, 25907, 'thrall - start'),
(56667, 7, 0, 'Taretha...  Cairne...  Aggra...  I will not fail you.  I will not fail this world!', 12, 0, 100, 0, 0, 25908, 'thrall - start'),
(56667, 8, 0, '|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t Thrall imbues the tanks with the strength of the earth! You are the |cFF9900CC|Hspell:106218|h[Last Defender of Azeroth]|h|r!', 41, 0, 100, 0, 0, 0, 'Thrall - last defender of atheroth');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56781, 0, 0, '|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s prepares to unleash a |cFF9900CC|Hspell:106401|h[Twilight Onslaught]|h|r!', 41, 0, 100, 0, 0, 0, 'goriona - twilight onslaught'),
(56781, 1, 0, '|Tinterface\\icons\\spell_fire_twilightrainoffire.blp:0|t%s fires a |cFF9900CC|Hspell:110153|h[Broadside]|h|r at the Skyfire!', 41, 0, 100, 0, 0, 0, 'goriona - broadside'),
(56781, 2, 0, '%s screeches in pain and retreats into the swirling clouds.', 41, 0, 100, 0, 0, 0, 'goriona - low hp');
